// src/lib/social/comments/graph.ts
// Reading comments under our Facebook and Instagram posts, hiding one, and
// replying to one.
//
// 🔑 Permissions (1 Nov 2026, token regenerated by the owner):
//   read FB  — pages_read_user_content      hide/reply FB — pages_manage_engagement (+ Page task MODERATE)
//   read/hide/reply IG — instagram_manage_comments (+ IG "Community activity")
// ⚠️ Facebook comments are read with the PAGE token; Instagram with the
// system-user token, as the publisher does.

import { graph } from "@/lib/social/adapters/facebook";
import { isOurFirstComment } from "@/lib/social/firstComment";

export type RawComment = {
  platform: "facebook" | "instagram";
  commentId: string;
  postId: string;
  postSnippet: string;
  author: string | null;
  text: string;
  at: string | null;
};

type Fetch = typeof fetch;

async function call(doFetch: Fetch, url: string, init?: RequestInit): Promise<Record<string, unknown>> {
  const res = await doFetch(url, { ...init, signal: AbortSignal.timeout(15_000), cache: "no-store" });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown> & { error?: { message?: string; code?: number } };
  if (json.error || !res.ok) throw new Error(`Meta refused (${json.error?.code ?? res.status}): ${json.error?.message ?? "no detail"}`);
  return json;
}

const rows = (j: unknown) => ((j as { data?: Record<string, unknown>[] })?.data ?? []);
const str = (v: unknown) => (typeof v === "string" ? v : "");
const q = (token: string) => `access_token=${encodeURIComponent(token)}`;

/** Top-level comments on the Page's last 25 posts. Our own replies are nested, so they are not here. */
export async function facebookComments(pageId: string, pageToken: string, doFetch: Fetch = fetch): Promise<RawComment[]> {
  const posts = rows(await call(doFetch, graph(`${encodeURIComponent(pageId)}/published_posts`) +
    `?fields=id,message,comments.limit(50){id,from,message,created_time}&limit=25&${q(pageToken)}`));
  // ⛔ The Page's OWN comments (e.g. the first-comment link, #92) are not
  // visitors' comments: never drafted for, never classified — a link comment
  // would otherwise be hidden as spam. By author, and by tag when Meta hides it.
  const ours = (c: Record<string, unknown>) =>
    str((c.from as { id?: string } | undefined)?.id) === pageId || isOurFirstComment(str(c.message));
  return posts.flatMap((p) => rows(p.comments).filter((c) => !ours(c)).map((c) => ({
    platform: "facebook" as const,
    commentId: str(c.id),
    postId: str(p.id),
    postSnippet: str(p.message).slice(0, 80),
    // ⚠️ Usually absent: Meta hides most commenters from a Page token.
    author: str((c.from as { name?: string } | undefined)?.name) || null,
    text: str(c.message),
    at: str(c.created_time) || null,
  })));
}

/** Top-level comments on the account's last 25 posts. */
export async function instagramComments(igUserId: string, token: string, doFetch: Fetch = fetch): Promise<RawComment[]> {
  const media = rows(await call(doFetch, graph(`${encodeURIComponent(igUserId)}/media`) +
    `?fields=id,caption,comments.limit(50){id,username,text,timestamp}&limit=25&${q(token)}`));
  return media.flatMap((m) => rows(m.comments).map((c) => ({
    platform: "instagram" as const,
    commentId: str(c.id),
    postId: str(m.id),
    postSnippet: str(m.caption).slice(0, 80),
    author: str(c.username) || null,
    text: str(c.text),
    at: str(c.timestamp) || null,
  })));
}

/**
 * Hides a comment — ⛔ never deletes it. A hidden comment stays visible to its
 * writer and their friends, and can be un-hidden from the post; a deleted one
 * is gone, and deleting is not ours to do by machine.
 */
export async function hideComment(c: Pick<RawComment, "platform" | "commentId">, token: string, doFetch: Fetch = fetch): Promise<void> {
  const field = c.platform === "facebook" ? "is_hidden" : "hide";
  await call(doFetch, graph(encodeURIComponent(c.commentId)), {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ [field]: "true", access_token: token }).toString(),
  });
}

/** A public reply under the comment. Returns the reply's id. */
/** A top-level comment ON A POST, as the Page (Facebook only). Returns the comment id. */
export async function commentOnPost(postId: string, message: string, token: string, doFetch: Fetch = fetch): Promise<string> {
  const json = await call(doFetch, graph(`${encodeURIComponent(postId)}/comments`), {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ message, access_token: token }).toString(),
  });
  return str(json.id);
}

export async function replyToComment(c: Pick<RawComment, "platform" | "commentId">, message: string, token: string, doFetch: Fetch = fetch): Promise<string> {
  const edge = c.platform === "facebook" ? "comments" : "replies";
  const json = await call(doFetch, graph(`${encodeURIComponent(c.commentId)}/${edge}`), {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    // ⚠️ In the body, not the URL: a URL is a place text gets logged.
    body: new URLSearchParams({ message, access_token: token }).toString(),
  });
  return str(json.id);
}
